import test from 'node:test';import assert from 'node:assert/strict';import {createPlaytestRecorder} from '../playtest-recorder.js';
test('local playtest reports contain observed timing and bounded scalar events, never live state',()=>{let now=100;const recorder=createPlaytestRecorder({clock:()=>now,wallClock:()=> '2026-10-29T00:00:00Z',limit:3});assert.equal(recorder.record('dialog'),false);recorder.start({chapter:4,stage:'arrival',party:[0,1,2]});now=2600;recorder.record('hint',{stage:2,world:{secret:'no'},label:'a'.repeat(200)});let report=recorder.report();assert.equal(report.elapsedSeconds,3);assert.equal(report.events[1].at,2.5);assert.equal(report.events[1].world,undefined);assert.equal(report.events[1].label.length,160);report.events[1].stage=99;assert.equal(recorder.report().events[1].stage,2);recorder.record('battle');recorder.record('marker',{kind:'confusion'});assert.equal(recorder.report().droppedEvents,1);assert.equal(recorder.report().events.length,3);recorder.clear();assert.equal(recorder.report(),null);});
